"use client";

import * as React from "react";

import { type IfscResult, normalizeIfsc, validateIfsc } from "../../lib/ifsc";
import { cn, controlClasses, Field, FieldBadge, useFieldState } from "./field";

export interface IFSCInputProps
  extends Omit<
    React.ComponentProps<"input">,
    "value" | "defaultValue" | "onChange" | "type"
  > {
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  onValidationChange?: (result: IfscResult) => void;
  validateOn?: "blur" | "change";
  /** Name the bank once the code resolves. Default `true`. */
  showBank?: boolean;
  label?: string;
  description?: string;
  containerClassName?: string;
}

export function IFSCInput({
  value: controlledValue,
  defaultValue = "",
  onValueChange,
  onValidationChange,
  validateOn = "blur",
  showBank = true,
  label,
  description,
  className,
  containerClassName,
  id,
  onBlur,
  ...props
}: IFSCInputProps) {
  const reactId = React.useId();
  const inputId = id ?? `ifsc-${reactId}`;
  const messageId = `${inputId}-message`;

  const field = useFieldState<IfscResult>({
    value: controlledValue,
    defaultValue,
    onValueChange,
    onValidationChange,
    validate: validateIfsc,
    transform: (raw) =>
      normalizeIfsc(raw)
        .replace(/[^A-Z0-9]/g, "")
        .slice(0, 11),
    validateOn,
  });

  const bank = showBank && field.result.valid ? field.result.bank : undefined;
  // An unrecognised bank code is a hint, never an error — new banks and mergers
  // land faster than any bundled list can track.
  const hint =
    field.result.valid && field.result.unrecognisedBank
      ? "Valid format, but we don't recognise this bank code."
      : undefined;

  return (
    <Field
      id={inputId}
      messageId={messageId}
      label={label}
      message={field.error ?? hint ?? description}
      tone={field.error ? "error" : hint ? "hint" : "muted"}
      className={containerClassName}
    >
      <div className="relative">
        <input
          {...props}
          id={inputId}
          type="text"
          autoComplete="off"
          autoCapitalize="characters"
          autoCorrect="off"
          spellCheck={false}
          placeholder={props.placeholder ?? "HDFC0001234"}
          value={field.value}
          onChange={(event) => field.setValue(event.target.value)}
          onBlur={(event) => {
            field.markTouched();
            onBlur?.(event);
          }}
          aria-invalid={Boolean(field.error)}
          aria-describedby={messageId}
          className={cn(
            controlClasses({
              error: Boolean(field.error),
              success: field.success,
            }),
            "uppercase tracking-[0.12em]",
            bank && "pr-36",
            className,
          )}
        />
        {bank && <FieldBadge>{bank}</FieldBadge>}
      </div>
    </Field>
  );
}

"use client";

import { type ClassValue, clsx } from "clsx";
import { CircleAlert, Info } from "lucide-react";
import * as React from "react";
import { twMerge } from "tailwind-merge";

/**
 * Shared by every bharat-ui field. Defined here rather than imported from a
 * project's `@/lib/utils` so that installing a component can never overwrite
 * the consumer's own utils file.
 */
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

export type FieldTone = "error" | "hint" | "muted";

export interface FieldProps {
  id: string;
  /** Id of the element holding the message; wire this into aria-describedby. */
  messageId: string;
  label?: string;
  /** Resolved message text — an error, a warning, or the fallback description. */
  message?: string;
  tone?: FieldTone;
  className?: string;
  children: React.ReactNode;
}

/** Label + control + message, with the aria plumbing already correct. */
export function Field({
  id,
  messageId,
  label,
  message,
  tone = "muted",
  className,
  children,
}: FieldProps) {
  return (
    <div className={cn("w-full", className)}>
      {label && (
        <label htmlFor={id} className="mb-1.5 block text-sm font-medium">
          {label}
        </label>
      )}

      {children}

      {message && (
        <p
          id={messageId}
          // Only errors interrupt a screen reader; hints are read on focus.
          role={tone === "error" ? "alert" : undefined}
          className={cn(
            "mt-1.5 flex items-start gap-1.5 text-xs",
            tone === "error"
              ? "text-red-600 dark:text-red-400"
              : "text-neutral-500 dark:text-neutral-400",
          )}
        >
          {tone === "error" ? (
            <CircleAlert className="mt-px size-3.5 shrink-0" aria-hidden />
          ) : tone === "hint" ? (
            <Info className="mt-px size-3.5 shrink-0" aria-hidden />
          ) : null}
          {message}
        </p>
      )}
    </div>
  );
}

/** Border/ring classes shared by every text control, keyed on validity. */
export function controlClasses(state: {
  error?: boolean;
  success?: boolean;
}): string {
  return cn(
    "h-10 w-full rounded-lg border bg-transparent px-3 py-2 font-mono text-sm outline-none transition",
    "placeholder:font-sans placeholder:text-neutral-400 dark:placeholder:text-neutral-600",
    "disabled:cursor-not-allowed disabled:opacity-50",
    "focus-visible:ring-[3px]",
    state.error
      ? "border-red-500 focus-visible:ring-red-500/20"
      : state.success
        ? "border-emerald-500 focus-visible:ring-emerald-500/20"
        : "border-neutral-300 focus-visible:border-neutral-900 focus-visible:ring-neutral-900/10 dark:border-neutral-700 dark:focus-visible:border-neutral-300 dark:focus-visible:ring-neutral-100/10",
  );
}

export interface ValidationLike {
  valid: boolean;
  error?: { message: string };
}

/**
 * The controlled/uncontrolled + touched + report-upward logic every field here
 * needs. Kept in one place so all of them behave identically: errors appear on
 * blur by default, then update live once the user has been warned.
 */
export function useFieldState<T extends ValidationLike>(options: {
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  onValidationChange?: (result: T) => void;
  validate: (raw: string) => T;
  /** Optional input mask applied on every keystroke. */
  transform?: (raw: string) => string;
  validateOn?: "blur" | "change";
}) {
  const {
    value: controlled,
    defaultValue = "",
    onValueChange,
    onValidationChange,
    validate,
    transform,
    validateOn = "blur",
  } = options;

  const isControlled = controlled !== undefined;
  const [uncontrolled, setUncontrolled] = React.useState(defaultValue);
  const value = isControlled ? controlled : uncontrolled;
  const [touched, setTouched] = React.useState(false);

  const result = React.useMemo(() => validate(value), [value, validate]);

  // Report upward only when the outcome actually changes, so consumers can put
  // setState directly in the callback without a render loop.
  const lastReported = React.useRef<string>("");
  React.useEffect(() => {
    const key = JSON.stringify(result);
    if (key === lastReported.current) return;
    lastReported.current = key;
    onValidationChange?.(result);
  }, [result, onValidationChange]);

  const setValue = React.useCallback(
    (next: string) => {
      const masked = transform ? transform(next) : next;
      if (!isControlled) setUncontrolled(masked);
      onValueChange?.(masked);
    },
    [isControlled, onValueChange, transform],
  );

  const shouldValidate = validateOn === "change" || touched;
  const error =
    shouldValidate && value.trim() !== "" ? result.error?.message : undefined;

  return {
    value,
    setValue,
    result,
    touched,
    markTouched: () => setTouched(true),
    error,
    success: result.valid,
  };
}

/** Small right-aligned badge inside a control (bank name, entity type, …). */
export function FieldBadge({ children }: { children: React.ReactNode }) {
  return (
    <span className="pointer-events-none absolute right-2 top-1/2 flex max-w-[45%] -translate-y-1/2 items-center gap-1 truncate rounded-full bg-emerald-500/10 px-2 py-0.5 text-xs font-medium text-emerald-700 dark:text-emerald-400">
      {children}
    </span>
  );
}

/**
 * IFSC (Indian Financial System Code) validation.
 *
 * 11 characters: `AAAA0BBBBBB`
 *   - 1–4  bank code (letters)
 *   - 5    always `0`, reserved by RBI for future use
 *   - 6–11 branch code (alphanumeric)
 *
 * There is no checksum. The bank code list below covers the common banks so a
 * UI can name the bank as you type; an unrecognised code is a hint, never an
 * error, because new banks and mergers happen constantly. Branch-level detail
 * needs a lookup API (Razorpay's ifsc.razorpay.com is the usual free one).
 */

const IFSC_RE = /^[A-Z]{4}0[A-Z0-9]{6}$/;

/** Bank code (first four characters) → bank name. Best-effort; PRs welcome. */
export const IFSC_BANK_CODES: Readonly<Record<string, string>> = {
  SBIN: "State Bank of India",
  HDFC: "HDFC Bank",
  ICIC: "ICICI Bank",
  UTIB: "Axis Bank",
  KKBK: "Kotak Mahindra Bank",
  PUNB: "Punjab National Bank",
  BARB: "Bank of Baroda",
  CNRB: "Canara Bank",
  UBIN: "Union Bank of India",
  IOBA: "Indian Overseas Bank",
  IDIB: "Indian Bank",
  CBIN: "Central Bank of India",
  MAHB: "Bank of Maharashtra",
  UCBA: "UCO Bank",
  PSIB: "Punjab & Sind Bank",
  BKID: "Bank of India",
  IBKL: "IDBI Bank",
  IDFB: "IDFC FIRST Bank",
  YESB: "Yes Bank",
  INDB: "IndusInd Bank",
  RATN: "RBL Bank",
  FDRL: "Federal Bank",
  SIBL: "South Indian Bank",
  KVBL: "Karur Vysya Bank",
  TMBL: "Tamilnad Mercantile Bank",
  CIUB: "City Union Bank",
  KARB: "Karnataka Bank",
  DLXB: "Dhanlaxmi Bank",
  JAKA: "Jammu & Kashmir Bank",
  BDBL: "Bandhan Bank",
  AUBL: "AU Small Finance Bank",
  ESFB: "Equitas Small Finance Bank",
  UJVN: "Ujjivan Small Finance Bank",
  JSFB: "Jana Small Finance Bank",
  SURY: "Suryoday Small Finance Bank",
  FINO: "Fino Payments Bank",
  AIRP: "Airtel Payments Bank",
  IPOS: "India Post Payments Bank",
  PYTM: "Paytm Payments Bank",
  CITI: "Citibank",
  HSBC: "HSBC",
  SCBL: "Standard Chartered Bank",
  DEUT: "Deutsche Bank",
  DBSS: "DBS Bank India",
};

export type IfscErrorCode =
  | "empty"
  | "wrong_length"
  | "bad_shape"
  | "reserved_char";

export interface IfscResult {
  valid: boolean;
  normalized: string;
  bankCode?: string;
  bank?: string;
  branchCode?: string;
  /** Structurally fine but the bank code isn't in our list. Show, don't block. */
  unrecognisedBank?: boolean;
  error?: { code: IfscErrorCode; message: string };
}

function fail(
  code: IfscErrorCode,
  message: string,
  normalized: string,
): IfscResult {
  return { valid: false, normalized, error: { code, message } };
}

export function normalizeIfsc(input: string): string {
  return input.replace(/\s/g, "").toUpperCase();
}

export function validateIfsc(input: string): IfscResult {
  const ifsc = normalizeIfsc(input);

  if (!input.trim()) return fail("empty", "Enter an IFSC.", ifsc);
  if (ifsc.length !== 11) {
    return fail(
      "wrong_length",
      `An IFSC is 11 characters — ${ifsc.length} so far.`,
      ifsc,
    );
  }
  // Called out separately because it's the single most common IFSC typo.
  if (ifsc[4] !== "0") {
    return fail(
      "reserved_char",
      "The 5th character of an IFSC is always 0.",
      ifsc,
    );
  }
  if (!IFSC_RE.test(ifsc)) {
    return fail(
      "bad_shape",
      "An IFSC looks like HDFC0001234 — four letters, a 0, then six characters.",
      ifsc,
    );
  }

  const bankCode = ifsc.slice(0, 4);
  const bank = IFSC_BANK_CODES[bankCode];

  return {
    valid: true,
    normalized: ifsc,
    bankCode,
    bank,
    branchCode: ifsc.slice(5),
    unrecognisedBank: !bank,
  };
}
